import { test, expect } from '@playwright/test';

test.describe('Tablet Layout - Two Column Grid', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tablet-view');
  });

  test('should switch to two-column grid layout on tablet viewport', async ({ page }) => {
    // Set viewport to tablet size
    await page.setViewportSize({ width: 768, height: 1022 });

    // Verify two columns are visible
    const column1 = page.getByRole('region', { name: /column 1/i });
    const column2 = page.getByRole('region', { name: /column 2/i });
    await expect(column1).toBeVisible();
    await expect(column2).toBeVisible();

    // Verify content is displayed in two columns
    const contentItems = page.getByRole('article');
    const itemCount = await contentItems.count();
    expect(itemCount).toBeGreaterThan(0);

    // Verify items are arranged in two columns
    const firstItem = page.locator('[data-testid="content-item-1"]');
    const secondItem = page.locator('[data-testid="content-item-2"]');
    const thirdItem = page.locator('[data-testid="content-item-3"]');
    const fourthItem = page.locator('[data-testid="content-item-4"]');

    const firstItemBoundingBox = await firstItem.boundingBox();
    const secondItemBoundingBox = await secondItem.boundingBox();
    const thirdItemBoundingBox = await thirdItem.boundingBox();
    const fourthItemBoundingBox = await fourthItem.boundingBox();

    // Check if items are roughly in two columns
    const isFirstInCol1 = firstItemBoundingBox.x < 300;
    const isSecondInCol2 = secondItemBoundingBox.x > 350;
    const isThirdInCol1 = thirdItemBoundingBox.x < 300;
    const isFourthInCol2 = fourthItemBoundingBox.x > 350;

    expect(isFirstInCol1).toBe(true);
    expect(isSecondInCol2).toBe(true);
    expect(isThirdInCol1).toBe(true);
    expect(isFourthInCol2).toBe(true);
  });

  test('should handle layout switch gracefully when resizing from desktop to tablet', async ({ page }) => {
    // Start in desktop view
    await page.setViewportSize({ width: 1920, height: 1080 });
    const desktopLayout = page.getByRole('region', { name: /desktop layout/i });
    await expect(desktopLayout).toBeVisible();

    // Resize to tablet view
    await page.setViewportSize({ width: 768, height: 1020 });

    // Verify two-column grid is now active
    const column1 = page.getByRole('region', { name: /column 1/i });
    const column2 = page.getByRole('region', { name: /column 2/i });
    await expect(column1).toBeVisible();
    await expect(column2).toBeVisible();

    // Verify desktop layout is no longer visible
    await expect(desktopLayout).not.toBeVisible();

    // Verify content items are still accessible and visible
    const contentItems = page.getByRole('article');
    const itemCount = await contentItems.count();
    expect(itemCount).toBeGreaterThan(0);

    // Verify content is not overlapping
    const firstItem = page.locator('[data-testid="content-item-1"]');
    const secondItem = page.locator('[data-testid="content-item-2"]');
    const firstItemBox = await firstItem.boundingBox();
    const secondItemBox = await secondItem.boundingBox();

    expect(firstItemBox.y).toBeLessThan(secondItemBox.y);
  });
});
